/** \brief Request generated by the test and its expected result */
typedef struct
{
    uint8_t                      Request[ MODBUS_FRAME_MAX_LEN ];   /**< Address + PDU (without CRC)          */
    modBus_MsgLength_t           RequestLen;                        /**< Length of request                    */
    uint8_t                      Response[ MODBUS_FRAME_MAX_LEN ];  /**< Expected address + PDU (without CRC) */
    modBus_MsgLength_t           ResponseLen;                       /**< Length of expected response, 0 - none */
    modBus_MasterRequestStatus_t Status;                            /**< Expected result of master request    */
}   itModBus_Exchange_t;

