/**
 * \brief   Frame with invalid CRC is dropped by the slave, next valid request is answered.
 *
 * \details Write Single Register frame with inverted CRC is transmitted directly by the
 *          master physical layer, then the same request is sent by the master.
 *
 * \par Expected results
 * - Slave receives the corrupted frame, CRC error counted, no response, register unchanged.
 * - Valid request is answered and executed.
 */
void It_ModBus_CorruptedCrc_FrameDropped_NextRequestAnswered( void )
{
    static uint8_t corruptedFrame[ MODBUS_FRAME_MAX_LEN ];

    It_ModBus_Init( itModBus_Baudrate, MODBUS_PARITY_EVEN, MODBUS_STOPBIT_1, USART_XFER_MODE_ISR );

    /* Value before the request (model is updated by the request builder) */
    const uint16_t originalValue = itModBus_HoldingRegs[ 77u ];

    It_ModBus_Build_WSR( itModBus_Exchange, itModBus_SlaveAddr, 77u, 0x7777u );

    const uint16_t crc = It_ModBus_Crc16( itModBus_Exchange.Request, itModBus_Exchange.RequestLen );

    for( modBus_MsgLength_t byteIdx = 0u; itModBus_Exchange.RequestLen > byteIdx; byteIdx++ )
    {
        corruptedFrame[ byteIdx ] = itModBus_Exchange.Request[ byteIdx ];
    }

    corruptedFrame[ itModBus_Exchange.RequestLen       ] = (uint8_t)( ~crc & 0xFFu );
    corruptedFrame[ itModBus_Exchange.RequestLen + 1u  ] = (uint8_t)( ( ~crc >> 8u ) & 0xFFu );

    It_ModBus_HaltGuard_Mark();

    itModBus_MasterPhy.Set_Transmission_Start( corruptedFrame, itModBus_Exchange.RequestLen + MODBUS_CRC_LEN );
    It_ModBus_Run( 50u );

    (void)It_ModBus_Retry_IfHalted( ( 1u != itModBus_SlavePhy.Get_RxFrameCnt() ) || ( 0u != itModBus_SlavePhy.Get_ErrorCnt() ) );

    TEST_ASSERT_EQUAL_UINT32( 1u, itModBus_SlavePhy.Get_RxFrameCnt() );
    TEST_ASSERT_EQUAL_HEX8_ARRAY( corruptedFrame, itModBus_SlavePhy.Get_LastRxFrame(), itModBus_Exchange.RequestLen + MODBUS_CRC_LEN );
    TEST_ASSERT_EQUAL_UINT32( 1u, itModBus_SlaveTl.Get_StatCounter().crcErrorCount );
    TEST_ASSERT_EQUAL_UINT32( 0u, itModBus_SlavePhy.Get_TxFrameCnt() );
    TEST_ASSERT_EQUAL_UINT32( 0u, itModBus_MasterPhy.Get_RxFrameCnt() );
    TEST_ASSERT_EQUAL_HEX16( originalValue, itModBus_HoldingRegs[ 77u ] );

    It_ModBus_Execute( itModBus_Exchange );

    TEST_ASSERT_EQUAL_HEX16( 0x7777u, itModBus_HoldingRegs[ 77u ] );
}

