/* ========================== LOCAL FUNCTIONS =============================== */

/**
 * \brief Initializes time base, both stacks and their physical layers
 *
 * Stacks initialize physical layers in the first tasks (PhyInit). The line is
 * left to settle, then the records of the physical layers and statistics of
 * the slave are cleared.
 *
 * \param baudrate [in]: Baud rate of both buses
 * \param parity   [in]: Parity of both buses
 * \param stopBits [in]: Stop bits of both buses
 * \param xferMode [in]: Data transfer mode of both physical layers
 */
static void It_ModBus_Init( modBus_Baudrate_t baudrate, modBus_Parity_t parity,
                            modBus_StopBits_t stopBits, usart_XferMode_t xferMode )
{
    ItModBus::UsartPhy * const phys[] = { &itModBus_MasterPhy, &itModBus_SlavePhy };

    It_ModBus_Init_TimeBase();

    for( uint8_t phyIdx = 0u; ( sizeof( phys ) / sizeof( phys[ 0u ] ) ) > phyIdx; phyIdx++ )
    {
        phys[ phyIdx ]->Set_Baudrate( baudrate );
        phys[ phyIdx ]->Set_Parity( parity );
        phys[ phyIdx ]->Set_StopBits( stopBits );
        phys[ phyIdx ]->Set_XferMode( xferMode );
    }

    TEST_ASSERT_EQUAL( MODBUS_REQUEST_OK, itModBus_SlaveTl.Set_SlaveAddr( itModBus_SlaveAddr ) );
    itModBus_SlaveTl.Activate();

    /* Response of maximal length must fit into the timeout (eg. 320 ms at 9600 Bd) */
    itModBus_Master.Set_ResponseTimeout( ( ( MODBUS_FRAME_MAX_LEN * itModBus_CharBitsMax * 1000u ) / baudrate ) + itModBus_ResponseMargin );
    itModBus_Master.Set_TurnaroundDelay( itModBus_TurnaroundDelay );

    It_ModBus_Run( itModBus_SettleTimeMs );

    TEST_ASSERT_TRUE_MESSAGE( itModBus_MasterPhy.Get_InitOk(), "Master physical layer initialization failed" );
    TEST_ASSERT_TRUE_MESSAGE( itModBus_SlavePhy.Get_InitOk(),  "Slave physical layer initialization failed" );
    TEST_ASSERT_EQUAL( MODBUS_SLAVE_TL_STANDBY, itModBus_SlaveTl.Get_ModuleState() );

    itModBus_MasterPhy.Reset_Records();
    itModBus_SlavePhy.Reset_Records();
    itModBus_SlaveTl.Reset_StatCounter();
}


/**
 * \brief Initializes and starts time base of ModBus tasks (TIM2, 1 MHz, free running)
 *        and timer of debug halt detection (TIM6, 5 kHz, free running, not frozen in halt)
 */
static void It_ModBus_Init_TimeBase( void )
{
    const tim_PeriphId_t timers[]      = { IT_MODBUS_REF_TIM, IT_MODBUS_HALT_TIM };
    const uint32_t       frequencies[] = { 1000000u,          itModBus_HaltTimFreq };
    const tim_Counter_t  periods[]     = { 0xFFFFFFFFu,       0xFFFFu };

    for( uint8_t timIdx = 0u; ( sizeof( timers ) / sizeof( timers[ 0u ] ) ) > timIdx; timIdx++ )
    {
        tim_PeriphConfig_t timConfig;

        TEST_ASSERT_EQUAL( TIM_REQUEST_OK, Tim_Get_DefaultConfig( &timConfig ) );
        timConfig.PeriphId         = timers[ timIdx ];
        timConfig.TimerFrequency   = frequencies[ timIdx ];
        timConfig.RefreshFrequency = 1u;

        TEST_ASSERT_EQUAL( TIM_REQUEST_OK, Tim_Init( &timConfig ) );
        TEST_ASSERT_EQUAL( TIM_REQUEST_OK, Tim_Set_Period( timers[ timIdx ], periods[ timIdx ] ) );
        TEST_ASSERT_EQUAL( TIM_REQUEST_OK, Tim_Start( timers[ timIdx ] ) );
    }

    IT_MODBUS_HALT_TIM_UNFREEZE();
}


/**
 * \brief Starts observation of debug halts (start of exchange)
 */
static void It_ModBus_HaltGuard_Mark( void )
{
    (void)Tim_Get_Counter( IT_MODBUS_REF_TIM,  &itModBus_HaltRefMark );
    (void)Tim_Get_Counter( IT_MODBUS_HALT_TIM, &itModBus_HaltTimMark );
}


/**
 * \brief Repeats exchange with transport failure during debug halt
 *
 * Halt time is the difference of the halt timer (runs in halt) and the
 * reference timer (frozen in halt) since \ref It_ModBus_HaltGuard_Mark.
 * Disturbed exchange of random sequence is repeated in place (the caller
 * repeats it), in other test cases the whole test case is repeated after
 * reset (next stage). Without halt, after \ref itModBus_RetryMax repetitions
 * or without failure the test case checks the exchange.
 *
 * \param disturbed [in]: Exchange has transport failure
 *
 * \return true - the caller repeats the exchange
 */
static bool It_ModBus_Retry_IfHalted( bool disturbed )
{
    tim_Counter_t refCnt  = 0u;
    tim_Counter_t haltCnt = 0u;
    bool          repeat  = false;

    (void)Tim_Get_Counter( IT_MODBUS_REF_TIM,  &refCnt );
    (void)Tim_Get_Counter( IT_MODBUS_HALT_TIM, &haltCnt );

    const uint32_t runUs   = refCnt - itModBus_HaltRefMark;
    const uint32_t totalUs = (uint32_t)(uint16_t)( haltCnt - itModBus_HaltTimMark ) * itModBus_HaltTickUs;
    const bool     halted  = ( ( runUs + itModBus_HaltMinUs ) <= totalUs );

    if( ( true == disturbed ) && ( true == halted ) && ( true == itModBus_RepeatInPlace ) &&
        ( itModBus_RetryMax > itModBus_RepeatCnt ) )
    {
        TEST_MESSAGE( It_ModBus_Message( "Debug halt disturbed USART, exchange repeated ", itModBus_ExchangeIdx ) );

        itModBus_RepeatCnt++;
        repeat = true;
    }
    else if( ( true == disturbed ) && ( true == halted ) && ( false == itModBus_RepeatInPlace ) &&
             ( itModBus_RetryMax > IntegrationTesting_Get_Stage() ) )
    {
        TEST_MESSAGE( It_ModBus_Message( "Debug halt disturbed USART, test repeated, exchange ", itModBus_ExchangeIdx ) );

        IntegrationTesting_Set_ResetExpected();

        Nvic_Set_SystemReset();
    }
    else if( true == disturbed )
    {
        /* Failure is reported by the test case - halt time for analysis */
        TEST_MESSAGE( It_ModBus_Message( "Transport failure, debug halt [us]: ", ( totalUs > runUs ) ? ( totalUs - runUs ) : 0u ) );
    }
    else
    {
        /* Exchange is checked by the test case */
    }

    return ( repeat );
}


/** \brief One task period of both stacks */
static void It_ModBus_Tick( void )
{
    itModBus_Master.Task( itModBus_TaskTimeMs );
    itModBus_SlaveCore.Task( itModBus_TaskTimeMs );
}


/**
 * \brief Runs both stacks with 1 ms task period until condition is fulfilled or timeout
 *
 * \param condition [in]: Callable returning true when waiting is finished
 * \param timeoutMs [in]: Maximal waiting time [ms]
 *
 * \return Final value of condition
 */
template< typename CONDITION >
static bool It_ModBus_RunUntil( CONDITION condition, uint32_t timeoutMs )
{
    tim_Counter_t lastCnt   = 0u;
    tim_Counter_t actualCnt = 0u;
    uint32_t      elapsedMs = 0u;

    (void)Tim_Get_Counter( IT_MODBUS_REF_TIM, &lastCnt );

    while( ( false == condition() ) && ( timeoutMs > elapsedMs ) )
    {
        (void)Tim_Get_Counter( IT_MODBUS_REF_TIM, &actualCnt );


        if( itModBus_TaskPeriodUs <= ( actualCnt - lastCnt ) )
        {
            lastCnt += itModBus_TaskPeriodUs;
            elapsedMs++;

            It_ModBus_Tick();
        }
        else
        {
            /* Data handling in polling mode */
            Usart_Task();
        }
    }

    return ( condition() );
}


/**
 * \brief Runs both stacks for given time
 *
 * \param timeMs [in]: Time [ms]
 */
static void It_ModBus_Run( uint32_t timeMs )
{
    (void)It_ModBus_RunUntil( []() { return ( false ); }, timeMs );
}


/**
 * \brief Executes one exchange by the master and checks it on both sides
 *
 * \param exchange [in]: Request generated by the test and its expected result
 */
static void It_ModBus_Execute( const itModBus_Exchange_t &exchange )
{
    static uint8_t requestFrame [ MODBUS_FRAME_MAX_LEN ];
    static uint8_t responseFrame[ MODBUS_FRAME_MAX_LEN ];

    uint32_t slaveRxCnt  = 0u;
    uint32_t slaveTxCnt  = 0u;
    uint32_t masterRxCnt = 0u;
    bool     repeat      = false;

    modBus_MsgLength_t responseLen = 0u;

    /* Request frame with CRC calculated by the test */
    const uint16_t requestCrc = It_ModBus_Crc16( exchange.Request, exchange.RequestLen );

    for( modBus_MsgLength_t byteIdx = 0u; exchange.RequestLen > byteIdx; byteIdx++ )
    {
        requestFrame        [ byteIdx ] = exchange.Request[ byteIdx ];
        itModBus_MasterTxBuf[ byteIdx ] = exchange.Request[ byteIdx ];
    }

    requestFrame[ exchange.RequestLen      ] = (uint8_t)( requestCrc & 0xFFu );
    requestFrame[ exchange.RequestLen + 1u ] = (uint8_t)( requestCrc >> 8u );

    /*--------------------------- Master request -----------------------------*/
    itModBus_RepeatCnt = 0u;

    do
    {
        slaveRxCnt  = itModBus_SlavePhy.Get_RxFrameCnt();
        slaveTxCnt  = itModBus_SlavePhy.Get_TxFrameCnt();
        masterRxCnt = itModBus_MasterPhy.Get_RxFrameCnt();

        const uint32_t crcErrorCnt = itModBus_SlaveTl.Get_StatCounter().crcErrorCount;

        It_ModBus_HaltGuard_Mark();

        TEST_ASSERT_EQUAL_MESSAGE( MODBUS_REQUEST_OK,
                                   itModBus_Master.StartTransmit( exchange.RequestLen, itModBus_MasterTxBuf, itModBus_MasterRxBuf ),
                                   It_ModBus_Message( "Request not started, exchange ", itModBus_ExchangeIdx ) );

        (void)It_ModBus_RunUntil( []() { return ( MODBUS_MASTER_REQ_BUSY != itModBus_Master.Get_RequestStatus() ); },
                                  itModBus_ExchangeTimeout );

        /* Slave finishes its transmission / returns to standby */
        It_ModBus_Run( 2u );

        /* Transport failure (not content of a complete frame) possibly caused by debug halt */
        const uint32_t expectedMasterRxCnt = ( 0u < exchange.ResponseLen ) ? ( masterRxCnt + 1u ) : masterRxCnt;

        repeat = It_ModBus_Retry_IfHalted( ( 0u                  != itModBus_MasterPhy.Get_ErrorCnt()   ) ||
                                           ( 0u                  != itModBus_SlavePhy.Get_ErrorCnt()    ) ||
                                           ( ( slaveRxCnt + 1u ) != itModBus_SlavePhy.Get_RxFrameCnt()  ) ||
                                           ( expectedMasterRxCnt != itModBus_MasterPhy.Get_RxFrameCnt() ) ||
                                           ( exchange.Status     != itModBus_Master.Get_RequestStatus() ) );

        if( true == repeat )
        {
            /* Line settles, records of the disturbed exchange are discarded (requests are idempotent) */
            It_ModBus_Run( itModBus_SettleTimeMs );

            itModBus_DiscardedSlaveRx  += itModBus_SlavePhy.Get_RxFrameCnt()  - slaveRxCnt;
            itModBus_DiscardedMasterRx += itModBus_MasterPhy.Get_RxFrameCnt() - masterRxCnt;
            itModBus_DiscardedCrcError += itModBus_SlaveTl.Get_StatCounter().crcErrorCount - crcErrorCnt;

            itModBus_MasterPhy.Clear_Errors();
            itModBus_SlavePhy.Clear_Errors();
        }
        else
        {
            /* Exchange is checked */
        }
    }
    while( true == repeat );

    /* USART errors (error id, USART_XFER_ERROR_CNT - no error) */
    TEST_ASSERT_EQUAL_MESSAGE( USART_XFER_ERROR_CNT, itModBus_MasterPhy.Get_LastErrorId(),
                               It_ModBus_Message( "USART error (id) on master bus, exchange ", itModBus_ExchangeIdx ) );
    TEST_ASSERT_EQUAL_MESSAGE( USART_XFER_ERROR_CNT, itModBus_SlavePhy.Get_LastErrorId(),
                               It_ModBus_Message( "USART error (id) on slave bus, exchange ", itModBus_ExchangeIdx ) );
    TEST_ASSERT_EQUAL_UINT32( 0u, itModBus_MasterPhy.Get_ErrorCnt() );
    TEST_ASSERT_EQUAL_UINT32( 0u, itModBus_SlavePhy.Get_ErrorCnt() );

    /*------------------------- Request on slave side ------------------------*/
    TEST_ASSERT_EQUAL_UINT32_MESSAGE( slaveRxCnt + 1u, itModBus_SlavePhy.Get_RxFrameCnt(),
                                      It_ModBus_Message( "Request not received by slave, exchange ", itModBus_ExchangeIdx ) );
    TEST_ASSERT_EQUAL_UINT16_MESSAGE( exchange.RequestLen + MODBUS_CRC_LEN, itModBus_SlavePhy.Get_LastRxFrameLen(),
                                      It_ModBus_Message( "Request length on slave, exchange ", itModBus_ExchangeIdx ) );
    TEST_ASSERT_EQUAL_HEX8_ARRAY_MESSAGE( requestFrame, itModBus_SlavePhy.Get_LastRxFrame(), exchange.RequestLen + MODBUS_CRC_LEN,
                                          It_ModBus_Message( "Request received by slave, exchange ", itModBus_ExchangeIdx ) );
    TEST_ASSERT_EQUAL_HEX8_ARRAY_MESSAGE( requestFrame, itModBus_MasterPhy.Get_LastTxFrame(), exchange.RequestLen + MODBUS_CRC_LEN,
                                          It_ModBus_Message( "Request transmitted by master, exchange ", itModBus_ExchangeIdx ) );

    /*------------------------ Response on master side -----------------------*/
    if( 0u < exchange.ResponseLen )
    {
        const uint16_t responseCrc = It_ModBus_Crc16( exchange.Response, exchange.ResponseLen );

        for( modBus_MsgLength_t byteIdx = 0u; exchange.ResponseLen > byteIdx; byteIdx++ )
        {
            responseFrame[ byteIdx ] = exchange.Response[ byteIdx ];
        }

        responseFrame[ exchange.ResponseLen      ] = (uint8_t)( responseCrc & 0xFFu );
        responseFrame[ exchange.ResponseLen + 1u ] = (uint8_t)( responseCrc >> 8u );

        TEST_ASSERT_EQUAL_UINT32_MESSAGE( masterRxCnt + 1u, itModBus_MasterPhy.Get_RxFrameCnt(),
                                          It_ModBus_Message( "Response not received by master, exchange ", itModBus_ExchangeIdx ) );
        TEST_ASSERT_EQUAL_UINT16_MESSAGE( exchange.ResponseLen + MODBUS_CRC_LEN, itModBus_MasterPhy.Get_LastRxFrameLen(),
                                          It_ModBus_Message( "Response length on master, exchange ", itModBus_ExchangeIdx ) );
        TEST_ASSERT_EQUAL_HEX8_ARRAY_MESSAGE( responseFrame, itModBus_MasterPhy.Get_LastRxFrame(), exchange.ResponseLen + MODBUS_CRC_LEN,
                                              It_ModBus_Message( "Response received by master, exchange ", itModBus_ExchangeIdx ) );
        TEST_ASSERT_EQUAL_HEX8_ARRAY_MESSAGE( responseFrame, itModBus_SlavePhy.Get_LastTxFrame(), exchange.ResponseLen + MODBUS_CRC_LEN,
                                              It_ModBus_Message( "Response transmitted by slave, exchange ", itModBus_ExchangeIdx ) );

        TEST_ASSERT_EQUAL_MESSAGE( exchange.Status, itModBus_Master.Get_RequestStatus(),
                                   It_ModBus_Message( "Request status, exchange ", itModBus_ExchangeIdx ) );

        /* Response passed to the application of the master */
        TEST_ASSERT_EQUAL( MODBUS_RX_READY, itModBus_Master.Get_RxMessageStatus( &responseLen ) );
        TEST_ASSERT_EQUAL_UINT16( exchange.ResponseLen, responseLen );
        TEST_ASSERT_EQUAL_HEX8_ARRAY_MESSAGE( exchange.Response, itModBus_MasterRxBuf, exchange.ResponseLen,
                                              It_ModBus_Message( "Response of master application, exchange ", itModBus_ExchangeIdx ) );
    }
    else
    {
        /* No response - broadcast or other slave */
        TEST_ASSERT_EQUAL_UINT32_MESSAGE( slaveTxCnt, itModBus_SlavePhy.Get_TxFrameCnt(),
                                          It_ModBus_Message( "Unexpected response of slave, exchange ", itModBus_ExchangeIdx ) );
        TEST_ASSERT_EQUAL_UINT32( masterRxCnt, itModBus_MasterPhy.Get_RxFrameCnt() );
        TEST_ASSERT_EQUAL_MESSAGE( exchange.Status, itModBus_Master.Get_RequestStatus(),
                                   It_ModBus_Message( "Request status, exchange ", itModBus_ExchangeIdx ) );
    }

    /*----------------------------- Physical layer ---------------------------*/
    TEST_ASSERT_EQUAL_UINT32( 0u, itModBus_MasterPhy.Get_TxStartErrorCnt() );
    TEST_ASSERT_EQUAL_UINT32( 0u, itModBus_SlavePhy.Get_TxStartErrorCnt() );

    It_ModBus_Check_Model();

    itModBus_ExchangeIdx++;
}


/**
 * \brief Compares slave application data with the model of the test
 */
static void It_ModBus_Check_Model( void )
{
    TEST_ASSERT_EQUAL_HEX16_ARRAY_MESSAGE( itModBus_ModelHolding, itModBus_HoldingRegs, itModBus_HoldingRegsCnt,
                                           It_ModBus_Message( "Holding registers, exchange ", itModBus_ExchangeIdx ) );

    for( uint16_t bitIdx = 0u; itModBus_CoilsCnt > bitIdx; bitIdx++ )
    {
        TEST_ASSERT_EQUAL_MESSAGE( itModBus_ModelCoils[ bitIdx ], itModBus_Coils[ bitIdx ],
                                   It_ModBus_Message( "Coils, exchange ", itModBus_ExchangeIdx ) );
    }
}


/**
 * \brief Executes sequence of random exchanges
 *
 * \param exchangesCnt [in]: Count of exchanges
 */
static void It_ModBus_RandomSequence( uint32_t exchangesCnt )
{
    /* Long sequence - exchange disturbed by debug halt is repeated in place */
    itModBus_RepeatInPlace = true;

    for( uint32_t exchangeIdx = 0u; exchangesCnt > exchangeIdx; exchangeIdx++ )
    {
        It_ModBus_Generate_Random( itModBus_Exchange );
        It_ModBus_Execute( itModBus_Exchange );
    }

    /* Frames and CRC errors of repeated exchanges are not counted */
    TEST_ASSERT_EQUAL_UINT32( exchangesCnt, itModBus_SlavePhy.Get_RxFrameCnt()  - itModBus_DiscardedSlaveRx );
    TEST_ASSERT_EQUAL_UINT32( exchangesCnt, itModBus_MasterPhy.Get_RxFrameCnt() - itModBus_DiscardedMasterRx );
    TEST_ASSERT_EQUAL_UINT32( 0u, itModBus_SlaveTl.Get_StatCounter().crcErrorCount - itModBus_DiscardedCrcError );
}


/**
 * \brief Generates random request and its expected response (updates the model)
 *
 * \param exchange [out]: Generated exchange
 */
static void It_ModBus_Generate_Random( itModBus_Exchange_t &exchange )
{
    static uint16_t values[ itModBus_WmrQuantityMax ];
    static bool     bits  [ itModBus_CoilsCnt ];

    /* Quantities are mostly short, every 8th request is long */
    const uint16_t lengthLimit = ( 0u == It_ModBus_Random( 8u ) ) ? itModBus_HoldingRegsCnt : 16u;

    switch( It_ModBus_Random( 11u ) )
    {
        case 0u:
        {
            const uint16_t addr     = (uint16_t)It_ModBus_Random( itModBus_HoldingRegsCnt );
            const uint16_t maxQty   = ( ( itModBus_HoldingRegsCnt - addr ) < lengthLimit ) ? ( itModBus_HoldingRegsCnt - addr ) : lengthLimit;
            It_ModBus_Build_ReadRegs( exchange, MODBUS_FUNCTION_RHR, addr, (uint16_t)( 1u + It_ModBus_Random( maxQty ) ) );
            break;
        }

        case 1u:
        {
            const uint16_t addr = (uint16_t)It_ModBus_Random( itModBus_InputRegsCnt );
            It_ModBus_Build_ReadRegs( exchange, MODBUS_FUNCTION_RIR, addr,
                                      (uint16_t)( 1u + It_ModBus_Random( itModBus_InputRegsCnt - addr ) ) );
            break;
        }

        case 2u:
        {
            const uint16_t addr = (uint16_t)It_ModBus_Random( itModBus_CoilsCnt );
            It_ModBus_Build_ReadBits( exchange, MODBUS_FUNCTION_RC, addr,
                                      (uint16_t)( 1u + It_ModBus_Random( itModBus_CoilsCnt - addr ) ) );
            break;
        }

        case 3u:
        {
            const uint16_t addr = (uint16_t)It_ModBus_Random( itModBus_DiscreteCnt );
            It_ModBus_Build_ReadBits( exchange, MODBUS_FUNCTION_RDI, addr,
                                      (uint16_t)( 1u + It_ModBus_Random( itModBus_DiscreteCnt - addr ) ) );
            break;
        }

        case 4u:
        {
            /* Occasionally refused value - exception 0x04, register unchanged */
            const uint16_t value = ( 0u == It_ModBus_Random( 10u ) ) ? itModBus_RejectedValue
                                                                     : (uint16_t)It_ModBus_Random( 0x10000u );
            It_ModBus_Build_WSR( exchange, itModBus_SlaveAddr, (uint16_t)It_ModBus_Random( itModBus_HoldingRegsCnt ), value );

            if( itModBus_RejectedValue == value )
            {
                It_ModBus_Set_Exception( exchange, MODBUS_ERROR_SLAVE_DEVICE_FAILURE );
            }
            break;
        }

        case 5u:
            It_ModBus_Build_WSC( exchange, (uint16_t)It_ModBus_Random( itModBus_CoilsCnt ), ( 0u != It_ModBus_Random( 2u ) ) );
            break;

        case 6u:
        {
            const uint16_t addr     = (uint16_t)It_ModBus_Random( itModBus_HoldingRegsCnt );
            const uint16_t limit    = ( itModBus_WmrQuantityMax < lengthLimit ) ? itModBus_WmrQuantityMax : lengthLimit;
            const uint16_t maxQty   = ( ( itModBus_HoldingRegsCnt - addr ) < limit ) ? ( itModBus_HoldingRegsCnt - addr ) : limit;
            const uint16_t quantity = (uint16_t)( 1u + It_ModBus_Random( maxQty ) );

            for( uint16_t regIdx = 0u; quantity > regIdx; regIdx++ )
            {
                values[ regIdx ] = (uint16_t)It_ModBus_Random( itModBus_RejectedValue );
            }

            It_ModBus_Build_WMR( exchange, addr, quantity, values );
            break;
        }

        case 7u:
        {
            const uint16_t addr     = (uint16_t)It_ModBus_Random( itModBus_CoilsCnt );
            const uint16_t quantity = (uint16_t)( 1u + It_ModBus_Random( itModBus_CoilsCnt - addr ) );

            for( uint16_t bitIdx = 0u; quantity > bitIdx; bitIdx++ )
            {
                bits[ bitIdx ] = ( 0u != It_ModBus_Random( 2u ) );
            }

            It_ModBus_Build_WMC( exchange, addr, quantity, bits );
            break;
        }

        case 8u:
            It_ModBus_Build_MWR( exchange, (uint16_t)It_ModBus_Random( itModBus_HoldingRegsCnt ),
                                 (uint16_t)It_ModBus_Random( 0x10000u ), (uint16_t)It_ModBus_Random( 0x10000u ) );
            break;

        case 9u:
        {
            const uint16_t readAddr  = (uint16_t)It_ModBus_Random( itModBus_HoldingRegsCnt );
            const uint16_t writeAddr = (uint16_t)It_ModBus_Random( itModBus_HoldingRegsCnt );
            const uint16_t readLimit = ( ( itModBus_HoldingRegsCnt - readAddr ) < lengthLimit ) ? ( itModBus_HoldingRegsCnt - readAddr ) : lengthLimit;
            const uint16_t wrLimit   = ( itModBus_RwmrWriteMax < 16u ) ? itModBus_RwmrWriteMax : 16u;
            const uint16_t wrMaxQty  = ( ( itModBus_HoldingRegsCnt - writeAddr ) < wrLimit ) ? ( itModBus_HoldingRegsCnt - writeAddr ) : wrLimit;
            const uint16_t writeQty  = (uint16_t)( 1u + It_ModBus_Random( wrMaxQty ) );
            /* Response length limit: 3 + 2 * readQty <= 253 */
            const uint16_t readQty   = (uint16_t)( 1u + It_ModBus_Random( readLimit ) );

            for( uint16_t regIdx = 0u; writeQty > regIdx; regIdx++ )
            {
                values[ regIdx ] = (uint16_t)It_ModBus_Random( itModBus_RejectedValue );
            }

            It_ModBus_Build_RWMR( exchange, readAddr, readQty, writeAddr, writeQty, values );
            break;
        }

        default:
        {
            /* Exception - read behind the last holding register */
            It_ModBus_Start( exchange, itModBus_SlaveAddr, MODBUS_FUNCTION_RHR );
            It_ModBus_Put16( exchange.Request, exchange.RequestLen, (uint16_t)( itModBus_HoldingRegsCnt - It_ModBus_Random( 4u ) ) );
            It_ModBus_Put16( exchange.Request, exchange.RequestLen, 5u );
            It_ModBus_Set_Exception( exchange, MODBUS_ERROR_ILLEGAL_DATA_ADDRESS );
            break;
        }
    }
}


/**
 * \brief Returns pseudo-random number (xorshift32, fixed seed)
 *
 * \param range [in]: Range of the result (> 0)
 *
 * \return Number 0 ... range - 1
 */
static uint32_t It_ModBus_Random( uint32_t range )
{
    itModBus_RandomState ^= itModBus_RandomState << 13u;
    itModBus_RandomState ^= itModBus_RandomState >> 17u;
    itModBus_RandomState ^= itModBus_RandomState << 5u;

    return ( itModBus_RandomState % range );
}


/**
 * \brief Calculates ModBus RTU CRC (polynomial 0xA001 reflected, initial value
 *        0xFFFF) bit by bit - independent of the implementation of the stack
 *
 * \param data   [in]: Data
 * \param length [in]: Count of bytes
 *
 * \return CRC, low byte is transmitted first
 */
static uint16_t It_ModBus_Crc16( const uint8_t *data, modBus_MsgLength_t length )
{
    uint16_t crc = 0xFFFFu;

    for( modBus_MsgLength_t byteIdx = 0u; length > byteIdx; byteIdx++ )
    {
        crc ^= data[ byteIdx ];

        for( uint8_t bitIdx = 0u; 8u > bitIdx; bitIdx++ )
        {
            crc = ( 0u != ( crc & 0x0001u ) ) ? (uint16_t)( ( crc >> 1u ) ^ 0xA001u ) : (uint16_t)( crc >> 1u );
        }
    }

    return ( crc );
}

/*----------------------------- Request builders -----------------------------*/

/**
 * \brief Starts new exchange - request header, response header, expected status
 *
 * \param exchange     [out]: Exchange
 * \param slaveAddr    [in]: Slave address of the request
 * \param functionCode [in]: Function code
 */
static void It_ModBus_Start( itModBus_Exchange_t &exchange, uint8_t slaveAddr, uint8_t functionCode )
{
    exchange.RequestLen  = 0u;
    exchange.ResponseLen = 0u;
    exchange.Status      = MODBUS_MASTER_REQ_DONE;

    It_ModBus_Put8( exchange.Request,  exchange.RequestLen,  slaveAddr );
    It_ModBus_Put8( exchange.Request,  exchange.RequestLen,  functionCode );
    It_ModBus_Put8( exchange.Response, exchange.ResponseLen, slaveAddr );
    It_ModBus_Put8( exchange.Response, exchange.ResponseLen, functionCode );
}


/** \brief Appends byte to the buffer */
static void It_ModBus_Put8( uint8_t *buffer, modBus_MsgLength_t &length, uint8_t value )
{
    buffer[ length ] = value;
    length++;
}


/** \brief Appends 16 bit value (big endian) to the buffer */
static void It_ModBus_Put16( uint8_t *buffer, modBus_MsgLength_t &length, uint16_t value )
{
    It_ModBus_Put8( buffer, length, (uint8_t)( value >> 8u ) );
    It_ModBus_Put8( buffer, length, (uint8_t)( value & 0xFFu ) );
}


/**
 * \brief Replaces expected response by exception response
 *
 * \param exchange      [in/out]: Exchange
 * \param exceptionCode [in]: Expected exception code
 */
static void It_ModBus_Set_Exception( itModBus_Exchange_t &exchange, uint8_t exceptionCode )
{
    exchange.ResponseLen = 0u;

    It_ModBus_Put8( exchange.Response, exchange.ResponseLen, exchange.Request[ 0u ] );
    It_ModBus_Put8( exchange.Response, exchange.ResponseLen, (uint8_t)( exchange.Request[ 1u ] | itModBus_ExceptionFlag ) );
    It_ModBus_Put8( exchange.Response, exchange.ResponseLen, exceptionCode );
}


/** \brief Read Holding Registers (0x03) / Read Input Registers (0x04) */
static void It_ModBus_Build_ReadRegs( itModBus_Exchange_t &exchange, uint8_t functionCode, uint16_t addr, uint16_t quantity )
{
    const uint16_t * const regs = ( MODBUS_FUNCTION_RHR == functionCode ) ? itModBus_ModelHolding : itModBus_InputRegs;

    It_ModBus_Start( exchange, itModBus_SlaveAddr, functionCode );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, addr );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, quantity );

    It_ModBus_Put8( exchange.Response, exchange.ResponseLen, (uint8_t)( 2u * quantity ) );

    for( uint16_t regIdx = 0u; quantity > regIdx; regIdx++ )
    {
        It_ModBus_Put16( exchange.Response, exchange.ResponseLen, regs[ addr + regIdx ] );
    }
}


/** \brief Read Coils (0x01) / Read Discrete Inputs (0x02) - bits packed LSB first */
static void It_ModBus_Build_ReadBits( itModBus_Exchange_t &exchange, uint8_t functionCode, uint16_t addr, uint16_t quantity )
{
    const bool * const bits      = ( MODBUS_FUNCTION_RC == functionCode ) ? itModBus_ModelCoils : itModBus_Discrete;
    const uint8_t      byteCount = (uint8_t)( ( quantity + 7u ) / 8u );

    It_ModBus_Start( exchange, itModBus_SlaveAddr, functionCode );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, addr );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, quantity );

    It_ModBus_Put8( exchange.Response, exchange.ResponseLen, byteCount );

    for( uint8_t byteIdx = 0u; byteCount > byteIdx; byteIdx++ )
    {
        uint8_t dataByte = 0u;

        for( uint8_t bitIdx = 0u; ( 8u > bitIdx ) && ( quantity > ( ( byteIdx * 8u ) + bitIdx ) ); bitIdx++ )
        {
            if( true == bits[ addr + ( byteIdx * 8u ) + bitIdx ] )
            {
                dataByte |= (uint8_t)( 1u << bitIdx );
            }
        }

        It_ModBus_Put8( exchange.Response, exchange.ResponseLen, dataByte );
    }
}


/** \brief Write Single Register (0x06) - response echoes the request */
static void It_ModBus_Build_WSR( itModBus_Exchange_t &exchange, uint8_t slaveAddr, uint16_t addr, uint16_t value )
{
    It_ModBus_Start( exchange, slaveAddr, MODBUS_FUNCTION_WSR );
    It_ModBus_Put16( exchange.Request,  exchange.RequestLen,  addr );
    It_ModBus_Put16( exchange.Request,  exchange.RequestLen,  value );
    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, addr );
    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, value );

    /* Executed by addressed slave and on broadcast */
    if( ( ( itModBus_SlaveAddr == slaveAddr ) || ( MODBUS_BROADCAST_ADDR == slaveAddr ) ) &&
        ( itModBus_RejectedValue != value ) )
    {
        itModBus_ModelHolding[ addr ] = value;
    }
}


/** \brief Write Single Coil (0x05) - response echoes the request */
static void It_ModBus_Build_WSC( itModBus_Exchange_t &exchange, uint16_t addr, bool value )
{
    const uint16_t coilValue = ( true == value ) ? itModBus_CoilOn : 0x0000u;

    It_ModBus_Start( exchange, itModBus_SlaveAddr, MODBUS_FUNCTION_WSC );
    It_ModBus_Put16( exchange.Request,  exchange.RequestLen,  addr );
    It_ModBus_Put16( exchange.Request,  exchange.RequestLen,  coilValue );
    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, addr );
    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, coilValue );

    itModBus_ModelCoils[ addr ] = value;
}


/** \brief Write Multiple Registers (0x10) */
static void It_ModBus_Build_WMR( itModBus_Exchange_t &exchange, uint16_t addr, uint16_t quantity, const uint16_t *values )
{
    It_ModBus_Start( exchange, itModBus_SlaveAddr, MODBUS_FUNCTION_WMR );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, addr );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, quantity );
    It_ModBus_Put8 ( exchange.Request, exchange.RequestLen, (uint8_t)( 2u * quantity ) );

    for( uint16_t regIdx = 0u; quantity > regIdx; regIdx++ )
    {
        It_ModBus_Put16( exchange.Request, exchange.RequestLen, values[ regIdx ] );
        itModBus_ModelHolding[ addr + regIdx ] = values[ regIdx ];
    }

    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, addr );
    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, quantity );
}


/** \brief Write Multiple Coils (0x0F) - bits packed LSB first */
static void It_ModBus_Build_WMC( itModBus_Exchange_t &exchange, uint16_t addr, uint16_t quantity, const bool *values )
{
    const uint8_t byteCount = (uint8_t)( ( quantity + 7u ) / 8u );

    It_ModBus_Start( exchange, itModBus_SlaveAddr, MODBUS_FUNCTION_WMC );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, addr );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, quantity );
    It_ModBus_Put8 ( exchange.Request, exchange.RequestLen, byteCount );

    for( uint8_t byteIdx = 0u; byteCount > byteIdx; byteIdx++ )
    {
        uint8_t dataByte = 0u;

        for( uint8_t bitIdx = 0u; ( 8u > bitIdx ) && ( quantity > ( ( byteIdx * 8u ) + bitIdx ) ); bitIdx++ )
        {
            const uint16_t valueIdx = (uint16_t)( ( byteIdx * 8u ) + bitIdx );

            if( true == values[ valueIdx ] )
            {
                dataByte |= (uint8_t)( 1u << bitIdx );
            }

            itModBus_ModelCoils[ addr + valueIdx ] = values[ valueIdx ];
        }

        It_ModBus_Put8( exchange.Request, exchange.RequestLen, dataByte );
    }

    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, addr );
    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, quantity );
}


/** \brief Mask Write Register (0x16) - response echoes the request */
static void It_ModBus_Build_MWR( itModBus_Exchange_t &exchange, uint16_t addr, uint16_t andMask, uint16_t orMask )
{
    It_ModBus_Start( exchange, itModBus_SlaveAddr, MODBUS_FUNCTION_MWR );
    It_ModBus_Put16( exchange.Request,  exchange.RequestLen,  addr );
    It_ModBus_Put16( exchange.Request,  exchange.RequestLen,  andMask );
    It_ModBus_Put16( exchange.Request,  exchange.RequestLen,  orMask );
    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, addr );
    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, andMask );
    It_ModBus_Put16( exchange.Response, exchange.ResponseLen, orMask );

    const uint16_t result = (uint16_t)( ( itModBus_ModelHolding[ addr ] & andMask ) | ( orMask & (uint16_t)( ~andMask ) ) );

    if( itModBus_RejectedValue != result )
    {
        itModBus_ModelHolding[ addr ] = result;
    }
    else
    {
        /* Refused by setter - register unchanged */
        It_ModBus_Set_Exception( exchange, MODBUS_ERROR_SLAVE_DEVICE_FAILURE );
    }
}


/** \brief Read/Write Multiple Registers (0x17) - write is performed before read */
static void It_ModBus_Build_RWMR( itModBus_Exchange_t &exchange, uint16_t readAddr, uint16_t readQuantity,
                                  uint16_t writeAddr, uint16_t writeQuantity, const uint16_t *values )
{
    It_ModBus_Start( exchange, itModBus_SlaveAddr, MODBUS_FUNCTION_RWMR );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, readAddr );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, readQuantity );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, writeAddr );
    It_ModBus_Put16( exchange.Request, exchange.RequestLen, writeQuantity );
    It_ModBus_Put8 ( exchange.Request, exchange.RequestLen, (uint8_t)( 2u * writeQuantity ) );

    for( uint16_t regIdx = 0u; writeQuantity > regIdx; regIdx++ )
    {
        It_ModBus_Put16( exchange.Request, exchange.RequestLen, values[ regIdx ] );
        itModBus_ModelHolding[ writeAddr + regIdx ] = values[ regIdx ];
    }

    It_ModBus_Put8( exchange.Response, exchange.ResponseLen, (uint8_t)( 2u * readQuantity ) );

    for( uint16_t regIdx = 0u; readQuantity > regIdx; regIdx++ )
    {
        It_ModBus_Put16( exchange.Response, exchange.ResponseLen, itModBus_ModelHolding[ readAddr + regIdx ] );
    }
}


/**
 * \brief Creates failure message "<text><number>" (static buffer)
 *
 * \param text   [in]: Text
 * \param number [in]: Number appended to the text
 *
 * \return Message
 */
static const char *It_ModBus_Message( const char *text, uint32_t number )
{
    char     digits[ 10u ];
    uint8_t  digitsCnt = 0u;
    uint32_t msgIdx    = 0u;

    while( ( '\0' != text[ msgIdx ] ) && ( ( sizeof( itModBus_MessageBuf ) - sizeof( digits ) - 1u ) > msgIdx ) )
    {
        itModBus_MessageBuf[ msgIdx ] = text[ msgIdx ];
        msgIdx++;
    }

    do
    {
        digits[ digitsCnt ] = (char)( '0' + ( number % 10u ) );
        number /= 10u;
        digitsCnt++;
    }
    while( ( 0u < number ) && ( sizeof( digits ) > digitsCnt ) );

    while( 0u < digitsCnt )
    {
        digitsCnt--;
        itModBus_MessageBuf[ msgIdx ] = digits[ digitsCnt ];
        msgIdx++;
    }

    itModBus_MessageBuf[ msgIdx ] = '\0';

    return ( itModBus_MessageBuf );
}
